create table b2b_asset_deletions (created_at datetime(6) not null, next_attempt_at datetime(6) not null, target_id varchar(40) not null, id varchar(80) not null, kind enum ('FILL_SESSION','FRAME_IMAGE') not null, primary key (id)) engine=InnoDB;
create table b2b_fills (created_at datetime(6) not null, session_id bigint not null, id varchar(40) not null, image_id varchar(40) not null, project_id varchar(40) not null, frame_json TEXT not null, primary key (id)) engine=InnoDB;
create table b2b_frames (display_order integer not null, version integer not null, created_at datetime(6) not null, name varchar(30) not null, id varchar(40) not null, image_id varchar(40), project_id varchar(40) not null, layout enum ('GRID','STRIP') not null, windows_json TEXT not null, primary key (id)) engine=InnoDB;
create table b2b_images (height integer not null, width integer not null, created_at datetime(6) not null, source_image_id varchar(32) not null, content_type varchar(40) not null, id varchar(40) not null, primary key (id)) engine=InnoDB;
create table b2b_projects (created_at datetime(6) not null, published_at datetime(6), updated_at datetime(6) not null, id varchar(40) not null, slug varchar(40) not null, name varchar(60) not null, description varchar(120) not null, status enum ('DRAFT','LIVE','PAUSED') not null, primary key (id)) engine=InnoDB;
create table b2b_runtime_binding (id integer not null, environment varchar(10) not null, runtime_id varchar(32) not null, project_id varchar(40) not null, slug varchar(40) not null, primary key (id)) engine=InnoDB;
create table catalog_banners (height integer not null, hidden bit not null, sort_order integer not null, width integer not null, created_at datetime(6) not null, deleted_at datetime(6), purge_at datetime(6), updated_at datetime(6) not null, action varchar(20), chip_ko varchar(20), chip_en varchar(30), id varchar(32) not null, image_id varchar(32) not null, video_id varchar(32), title_ko varchar(60) not null, title_en varchar(90), body_ko varchar(120), body_en varchar(180), link_url varchar(500), primary key (id)) engine=InnoDB;
create table catalog_blobs (content_type varchar(40) not null, id varchar(40) not null, data LONGBLOB not null, primary key (id)) engine=InnoDB;
create table catalog_builtin_frames (height integer, hidden bit not null, pro bit, width integer, deleted_at datetime(6), updated_at datetime(6) not null, badge_ko varchar(20), id varchar(32) not null, image_id varchar(32), badge_en varchar(40), title_ko varchar(40), title_en varchar(60), subtitle_ko varchar(80), subtitle_en varchar(120), windows_json TEXT, primary key (id)) engine=InnoDB;
create table catalog_frames (height integer not null, hidden bit not null, pro bit, sort_order integer not null, width integer not null, created_at datetime(6) not null, deleted_at datetime(6), purge_at datetime(6), updated_at datetime(6) not null, badge_ko varchar(20), id varchar(32) not null, image_id varchar(32) not null, badge_en varchar(40), title_ko varchar(40) not null, title_en varchar(60), subtitle_ko varchar(80), subtitle_en varchar(120), windows_json TEXT not null, primary key (id)) engine=InnoDB;
create table catalog_images (duration_ms integer, height integer not null, size_bytes integer not null, width integer not null, created_at datetime(6) not null, id varchar(32) not null, content_type varchar(40) not null, primary key (id)) engine=InnoDB;
create table catalog_pose_overrides (hidden bit not null, created_at datetime(6) not null, deleted_at datetime(6), id bigint not null auto_increment, purge_at datetime(6), updated_at datetime(6) not null, version varchar(20) not null, shot varchar(80) not null, labels_json TEXT, primary key (id)) engine=InnoDB;
create table catalog_pose_uploads (height integer not null, hidden bit not null, sort_order integer not null, width integer not null, created_at datetime(6) not null, deleted_at datetime(6), purge_at datetime(6), updated_at datetime(6) not null, id varchar(32) not null, image_id varchar(32) not null, labels_json TEXT not null, primary key (id)) engine=InnoDB;
create table fill_images (size_bytes integer not null, created_at datetime(6), session_id bigint not null, id varchar(32) not null, content_type varchar(40) not null, data LONGBLOB not null, primary key (id)) engine=InnoDB;
create table fill_queue (from_slot integer not null, filled_at datetime(6), filled_by_id bigint, id bigint not null auto_increment, queued_at datetime(6) not null, session_id bigint not null, clip_id varchar(32), image_id varchar(32) not null, filled_by_name varchar(40), primary key (id)) engine=InnoDB;
create table fill_sessions (borderless bit not null, frame_locked boolean default false not null, created_at datetime(6), expires_at datetime(6) not null, id bigint not null auto_increment, owner_id bigint not null, code varchar(12) not null, frame varchar(20) not null, layout varchar(20) not null, title varchar(30), gif_image_id varchar(32), art_frame_id varchar(40), custom_frame_json TEXT, primary key (id)) engine=InnoDB;
create table fill_slots (slot_index integer not null, filled_at datetime(6), filled_by_id bigint, id bigint not null auto_increment, session_id bigint not null, clip_id varchar(32), image_id varchar(32), filled_by_name varchar(40), primary key (id)) engine=InnoDB;
create table users (created_at datetime(6), deleted_at datetime(6), id bigint not null auto_increment, apple_refresh_token varchar(1024), device_id varchar(255), nickname varchar(255), oauth_id varchar(255), oauth_provider varchar(255), profile_image varchar(255), role enum ('ADMIN','USER') not null, primary key (id)) engine=InnoDB;
